// Kiosk-mode JavaScript - Android 5.0 compatible (ES5 only, no arrow functions, no const/let, no Promises)
const KIOSK_JS = `
  // Inactivity timeout - return to home after 90 seconds of no interaction
  var inactivityTimer;
  var INACTIVITY_MS = 90000;
  var countdownTimer;
  var remainingSeconds = Math.floor(INACTIVITY_MS / 1000);

  function resetInactivityTimer() {
    clearTimeout(inactivityTimer);
    clearInterval(countdownTimer);
    remainingSeconds = Math.floor(INACTIVITY_MS / 1000);
    updateCountdown();
    inactivityTimer = setTimeout(function() {
      window.location.href = '/kiosk-lite';
    }, INACTIVITY_MS);
    countdownTimer = setInterval(function() {
      remainingSeconds = remainingSeconds - 1;
      if (remainingSeconds <= 0) {
        clearInterval(countdownTimer);
        return;
      }
      updateCountdown();
    }, 1000);
  }

  function updateCountdown() {
    var el = document.getElementById('kiosk-countdown');
    if (!el) return;
    var m = Math.floor(remainingSeconds / 60);
    var s = remainingSeconds % 60;
    if (s < 10) s = '0' + s;
    el.textContent = m + ':' + s;
    // Change color when low
    if (remainingSeconds <= 15) {
      el.style.color = '#ff6b6b';
    } else if (remainingSeconds <= 30) {
      el.style.color = '#FFD439';
    }
  }

  // Listen for user activity
  document.addEventListener('touchstart', resetInactivityTimer, false);
  document.addEventListener('click', resetInactivityTimer, false);
  document.addEventListener('keydown', resetInactivityTimer, false);

  // Start timer on page load
  resetInactivityTimer();

  // Update clock display
  function updateClock() {
    var el = document.getElementById('kiosk-clock');
    if (!el) return;
    var now = new Date();
    var h = now.getHours();
    var m = now.getMinutes();
    var ampm = h >= 12 ? 'PM' : 'AM';
    h = h % 12;
    if (h === 0) h = 12;
    if (m < 10) m = '0' + m;
    el.textContent = h + ':' + m + ' ' + ampm;
  }
  updateClock();
  setInterval(updateClock, 30000);

  // Try to enter fullscreen (works in some WebView versions)
  function tryFullscreen() {
    var el = document.documentElement;
    if (el.requestFullscreen) {
      el.requestFullscreen();
    } else if (el.webkitRequestFullscreen) {
      el.webkitRequestFullscreen();
    }
  }
  // Auto-enter fullscreen on first touch
  document.addEventListener('touchstart', function() {
    tryFullscreen();
  }, { once: true });

  // ---- White Screen Protection (ES5 compatible) ----
  // When the kiosk is left on-screen for hours, the browser may throttle/freeze
  // the WebView, causing a blank white screen. This monitors for that and recovers.
  var _wsHiddenAt = null;
  var _wsLastHeartbeat = Date.now();
  var _wsHeartbeatInterval = null;

  // Track when page goes hidden/visible
  document.addEventListener('visibilitychange', function() {
    if (document.hidden) {
      _wsHiddenAt = Date.now();
    } else {
      if (_wsHiddenAt !== null) {
        var hiddenMs = Date.now() - _wsHiddenAt;
        _wsHiddenAt = null;
        if (hiddenMs > 300000) {
          // Hidden for more than 5 minutes — full reload
          window.location.reload();
        } else if (hiddenMs > 30000) {
          // Hidden 30s-5min — refresh data by reloading
          window.location.reload();
        }
      }
      _wsLastHeartbeat = Date.now();
    }
  }, false);

  // Self-healing: check every 2 minutes for white screen or frozen state
  _wsHeartbeatInterval = setInterval(function() {
    var now = Date.now();
    var elapsed = now - _wsLastHeartbeat;

    // Update heartbeat (this line itself proves JS is running)
    _wsLastHeartbeat = now;

    // Check if body is empty/white (DOM might have been cleared by browser)
    var body = document.body;
    if (body) {
      var hasContent = body.innerHTML && body.innerHTML.length > 50;
      if (!hasContent) {
        // Body is empty — force reload
        window.location.reload();
        return;
      }
    }

    // Check if the main container exists
    var container = document.querySelector('.container');
    if (!container) {
      // Main container missing — force reload
      window.location.reload();
      return;
    }
  }, 120000); // every 2 minutes

  // Periodic data refresh: reload every 5 minutes to keep box data fresh
  // Only if on the home/locker screen (no active payment or form)
  setInterval(function() {
    var activeForm = document.querySelector('form');
    var paymentSection = document.getElementById('payment-qr');
    if (!activeForm && !paymentSection) {
      // Check network before reloading to avoid reload loops during outages
      if (navigator.onLine) {
        window.location.reload();
      }
    }
  }, 300000); // every 5 minutes

  // ---- AJAX Payment Polling (Chrome 37 compatible) ----
  // Replaces meta-refresh so QR code stays visible while checking payment status
  function startPaymentPolling(pollUrl, checkIntervalMs) {
    var pollInterval = setInterval(function() {
      var xhr = new XMLHttpRequest();
      xhr.open('GET', pollUrl, true);
      xhr.setRequestHeader('Accept', 'application/json');
      xhr.onreadystatechange = function() {
        if (xhr.readyState !== 4) return;
        if (xhr.status !== 200) return;
        try {
          var resp = JSON.parse(xhr.responseText);
          if (resp && resp.status === 'completed') {
            clearInterval(pollInterval);
            // Payment confirmed — redirect to success page
            window.location.href = resp.redirectUrl || '/kiosk-lite?action=payment-success&msg=' + encodeURIComponent(resp.message || 'Payment confirmed!');
          } else if (resp && resp.status === 'failed') {
            clearInterval(pollInterval);
            window.location.href = '/kiosk-lite?action=error&msg=' + encodeURIComponent(resp.message || 'Payment failed');
          }
        } catch(e) {
          // Non-JSON response — ignore, keep polling
        }
      };
      xhr.send();
    }, checkIntervalMs || 5000);
  }
`;

